else:
	sa = suffix_array(s)
	(lcp, rank) = calc_lcp(s, sa)
	ind = rank[indStart[0]]
	for st in indStart:
		ind = min(ind, rank[st])
	resp = len(indEnd) - lower_bound(indEnd, sa[ind] + max(0, len(start) - len(end)))
	while ind < len(lcp) and lcp[ind] >= len(start):
